            UNLESS CONFLICT
            ''',
            [],
        )

        await self.assert_query_result(
            r'''
            INSERT Baz { foo := "!", bar := "bar" }
            UNLESS CONFLICT
            ''',
            [],
        )

        await self.assert_query_result(
            r'''
